        sisterModels: [ { name: "Audi A4 (B9) 40 TFSI", note: "Shares the exact same EA888 Gen 4 mild-hybrid powertrain." }, { name: "Audi Q5 (FY) 40 TFSI", note: "Utilizes the same ultra-efficient B-cycle engine." } ],
        tuningPotential: [ { stage: "Stage 1", power: "245 - 255 hp", notes: "Due to the extreme 11.6:1 compression ratio, tuning must be handled very carefully to avoid knock. A 98+ RON map is absolutely mandatory. Yields approx 400 Nm.", zeroToHundred: "6.8s", hundredToTwoHundred: "18.5s" }, { stage: "Stage 2", power: "270 - 285 hp", notes: "Requires a 3-inch downpipe, OPF delete (where legal), and an upgraded intercooler. The high compression ratio severely limits further safe power gains on pump gas.", zeroToHundred: "6.2s", hundredToTwoHundred: "16.0s" }, { stage: "Stage 3 (IS20/IS38 Swap)", power: "320 - 340 hp", notes: "Swapping to a larger turbo requires extreme caution, water/meth injection, and very conservative ignition timing to prevent blowing the ring lands due to the B-cycle compression.", zeroToHundred: "5.5s", hundredToTwoHundred: "12.8s" } ],
