        fluidCapacities: [ { system: "Engine Oil", capacity: "7.2 Liters", spec: "VW 508.00 0W-20" }, { system: "Coolant", capacity: "12.5 Liters", spec: "G12evo" }, { system: "Automatic Trans (DL382)", capacity: "4.0 Liters", spec: "DL382 DSG Fluid" }, { system: "Brake Fluid", capacity: "1.0 Liter", spec: "DOT 4" }, { system: "Quattro Ultra Clutch", capacity: "0.5 Liters", spec: "AWD Transfer Fluid" }, { system: "Fuel Tank", capacity: "63 Liters (73L Opt)", spec: "95+ RON Unleaded (98 RON Recommended)" } ],
        torqueSpecs: [ { part: "Oil Drain Plug", value: "30 Nm", note: "Replace copper crush washer." }, { part: "Spark Plugs", value: "30 Nm", note: "Torque carefully into the aluminum head." }, { part: "Wheel Bolts", value: "120 Nm", note: "Tighten strictly in a star pattern." }, { part: "Turbo V-Band Clamps", value: "12 Nm", note: "Ensure perfect seating to prevent exhaust leaks in the valley." }, { part: "PCV Bolts", value: "9 Nm", note: "Tighten evenly in a crisscross pattern." }, { part: "Water Pump Bolts", value: "9 Nm", note: "Tighten evenly to avoid cracking the housing." } ],
        engineeringData: { blockDesign: "All-Aluminum 90-degree V6 (EA839 architecture).", crankshaft: "Forged Steel, 4 main bearings.", pistonSpeed: "14.8 m/s @ 6000 RPM.", alternator: "48V Belt Alternator Starter (BAS) Mild Hybrid System.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with friction-optimized skirts.", wristPinDiameter: "22 mm", connectingRodLength: "153 mm", rodBoltSize: "M9 x 1.0", crankMainJournal: "65.0 mm", crankRodJournal: "54.0 mm", rodRatio: "1.72" }, cylinderHead: { combustionChamberVol: "44.0 cc", intakePortFlow: "24-valve DOHC. Features Audi Valvelift System (AVS) on the intake side for B-cycle efficiency.", valveSizes: "Intake: 33.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Quad cams. Intake closes incredibly early during the compression stroke.", lifterType: "Hydraulic roller rockers (Rocker arm defect resolved in this iteration).", specialFeature: "Hot-V turbocharger placement minimizes exhaust routing and drastically improves spool time." }, oilAndCooling: { oilSquirters: "Yes (Under-piston cooling jets).", oilPumpType: "Fully variable displacement vane pump.", thermostatOpening: "Electronically managed thermal management module.", oilCooler: "Water-to-Oil heat exchanger located in the engine V." }, fuelSystem: { systemType: "Direct Injection (FSI).", maxPressure: "250 Bar.", injectors: "6x High-Pressure FSI." }, tuningLimits: { maxSafeTorqueStock: "Approx. 550 Nm (DL382 transmission limit without TCU tune).", maxSafePowerStock: "Approx. 450 hp (Factory turbo limit).", maxSafeRPM: "6800 RPM", weakestLink: "The OPF restricts airflow heavily. The 48V BAS system and the transmission clutch clamping pressure are the other main limits." }, electrical: { coils: "6x Individual COP units.", ecu: "Bosch MG1" } },
