        tuningPotential: [ { stage: "Stage 1", power: "200 - 210 hp", notes: "Because the DTNA is a software-detuned engine aimed at corporate fleet markets, an ECU remap safely brings this engine past 200hp, offering phenomenal value.", zeroToHundred: "7.9s", hundredToTwoHundred: "21.0s" }, { stage: "Stage 2", power: "215 - 225 hp", notes: "Requires a DPF/SCR delete (where legal) and a turbo-back exhaust. The factory water-cooled intercooler is excellent, but the small turbocharger runs out of breath quickly.", zeroToHundred: "7.5s", hundredToTwoHundred: "19.0s" }, { stage: "Stage 3", power: "250 - 260+ hp", notes: "Requires a GTD1449VZ turbo upgrade, larger injectors, and a DL382 TCU tune. The EA288evo block handles this effortlessly.", zeroToHundred: "6.6s", hundredToTwoHundred: "16.5s" } ],
