        tuningPotential: [ { stage: "Stage 1", power: "235 - 245 hp", notes: "An EDC17 ECU remap safely brings this engine to nearly 245hp and 480 Nm of torque, offering phenomenal value.", zeroToHundred: "7.1s", hundredToTwoHundred: "19.0s" }, { stage: "Stage 2", power: "255 - 265 hp", notes: "Requires a DPF/SCR delete (where legal) and a turbo-back exhaust. The factory water-cooled intercooler is excellent, but the turbocharger runs out of breath quickly.", zeroToHundred: "6.8s", hundredToTwoHundred: "17.5s" }, { stage: "Stage 3", power: "280 - 300+ hp", notes: "Requires a GTD1752VRK turbo upgrade, larger injectors, and a DL382 TCU tune. The EA288evo block handles this effortlessly.", zeroToHundred: "6.1s", hundredToTwoHundred: "14.5s" } ],
        tuningGraphData: { stock: { hp: 204, nm: 400 }, stage1: { hp: 240, nm: 480 }, stage2: { hp: 260, nm: 500 }, stage3: { hp: 290, nm: 550 } },
        model3DPath: "/images/brands/audi/A6/C8/test2.glb", model3DScale: 0.25, model3DRotation: [0, 3.14, 0], manualLightPositions: {}, riskRating: 4, lightSettings: { headlightAngle: 0.25, headlightIntensity: 200, headlightOpacity: 0.5, headlightRadiusTop: 0.02, headlightTargetDistance: 4.5, headlightPenumbra: 0.1, meshGlowHeadlight: 10, meshGlowTaillight: 13, meshGlowDrl: 8, useBloom: true }, hotspotSettings: {}, 
