        fluidCapacities: [ { system: "Engine Oil", capacity: "6.1 Liters", spec: "VW 507.00 5W-30" }, { system: "Coolant", capacity: "12.0 Liters", spec: "G12evo" }, { system: "Automatic Trans (ZF8)", capacity: "8.5 Liters", spec: "ZF Lifeguard 8" }, { system: "Brake Fluid", capacity: "1.0 Liter", spec: "DOT 4" }, { system: "Front Differential", capacity: "1.0 Liter", spec: "75W-90 GL-4" }, { system: "AdBlue / DEF", capacity: "24.0 Liters", spec: "ISO 22241-1" } ],
        torqueSpecs: [ { part: "Oil Drain Plug", value: "30 Nm", note: "Replace copper crush washer." }, { part: "Injector Clamps", value: "10 Nm + 90 degrees", note: "Strictly one-time use stretch bolts. Crucial to prevent blow-by." }, { part: "Glow Plugs", value: "15 Nm", note: "Extremely fragile. Soak in penetrating oil before removal." }, { part: "Wheel Bolts", value: "120 Nm", note: "Tighten strictly in a star pattern." }, { part: "Upper Chain Tensioner Bolts", value: "9 Nm", note: "Tighten evenly." }, { part: "Oil Cooler Bolts", value: "10 Nm", note: "Replace seals when performing this job." } ],
        engineeringData: { blockDesign: "Cast Iron 90-degree V6 closed deck (EA897evo2).", crankshaft: "Forged Steel, 4 main bearings.", pistonSpeed: "14.2 m/s @ 4500 RPM.", alternator: "48V Belt Alternator Starter (BAS) Mild Hybrid System.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with internal oil cooling channels.", wristPinDiameter: "30 mm", connectingRodLength: "154 mm", rodBoltSize: "M9 x 1.0", crankMainJournal: "65.0 mm", crankRodJournal: "60.0 mm", rodRatio: "1.79" }, cylinderHead: { combustionChamberVol: "In piston bowl", intakePortFlow: "24-valve DOHC crossflow.", valveSizes: "Intake: 29.0 mm / Exhaust: 26.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Quad cams driven by rear chains.", lifterType: "Hydraulic roller rockers.", specialFeature: "Piezo injectors can trigger up to 5 individual injection events per cycle for extreme noise reduction and efficiency." }, oilAndCooling: { oilSquirters: "Yes (Under-piston cooling jets).", oilPumpType: "Chain-driven fully variable.", thermostatOpening: "Electronically managed.", oilCooler: "Water-to-Oil heat exchanger located deep in the engine V-valley." }, fuelSystem: { systemType: "Common Rail. Bosch CP4.2 Dual-Plunger High-Pressure Fuel Pump. Features Euro 6 SCR AdBlue injection.", maxPressure: "2000 Bar.", injectors: "Bosch Piezoelectric." }, tuningLimits: { maxSafeTorqueStock: "Approx. 800 Nm (ZF8 limits)", maxSafePowerStock: "Approx. 350 hp (Turbo flow limit)", maxSafeRPM: "4800 RPM", weakestLink: "The Bosch CP4.2 fuel pump, the 48V BAS system, and the factory intercooler." }, electrical: { coils: "Compression Ignition", ecu: "Bosch MD1" } },
