        tuningPotential: [ { stage: "Stage 1", power: "350 - 360 hp", notes: "An ECU software flash unlocks the detuned ICE, bringing the combined output to 360+ hp and over 550 Nm of torque. EV motor mapping remains stock for safety.", zeroToHundred: "5.5s", hundredToTwoHundred: "14.5s" }, { stage: "Stage 2", power: "370 - 380 hp", notes: "Requires a high-flow downpipe and upgraded intercooler. The DL382e TCU must be tuned to increase clamping pressure for the hybrid clutch.", zeroToHundred: "5.1s", hundredToTwoHundred: "13.0s" }, { stage: "Stage 3 (IS38 Swap)", power: "420 - 450+ hp", notes: "Swapping to the IS38 turbo transforms the ICE component. The torque must be carefully mapped to avoid destroying the hybrid integration clutch.", zeroToHundred: "4.6s", hundredToTwoHundred: "11.2s" } ],
