        tuningPotential: [ { stage: "Stage 1", power: "400 - 420 hp", notes: "An ECU software flash unlocks massive combined potential. The ICE component is safely pushed to 310+ hp, resulting in a combined output exceeding 420 hp. EV motor mapping remains stock for safety.", zeroToHundred: "4.8s", hundredToTwoHundred: "12.5s" }, { stage: "Stage 2", power: "420 - 440 hp", notes: "Requires a high-flow downpipe and upgraded intercooler. The DL382e TCU must be tuned to increase clamping pressure for the hybrid clutch.", zeroToHundred: "4.5s", hundredToTwoHundred: "11.5s" }, { stage: "Stage 3 (IS38 Swap)", power: "460 - 480+ hp", notes: "Swapping to the IS38 turbo transforms the ICE component. The torque must be carefully mapped to avoid destroying the hybrid integration clutch.", zeroToHundred: "4.1s", hundredToTwoHundred: "10.2s" } ],
