            tuningPotential: [ { stage: "Stage 1", power: "240 - 250 hp", notes: "An MD1 ECU remap safely brings this engine to nearly 250hp and 480 Nm of torque, offering phenomenal value.", zeroToHundred: "7.1s", hundredToTwoHundred: "19.0s" }, { stage: "Stage 2", power: "260 - 270 hp", notes: "Requires a DPF/SCR delete (where legal) and a turbo-back exhaust. The factory water-cooled intercooler is excellent, but the turbocharger runs out of breath quickly.", zeroToHundred: "6.8s", hundredToTwoHundred: "17.5s" }, { stage: "Stage 3", power: "290 - 310+ hp", notes: "Requires a GTD1752VRK turbo upgrade, larger injectors, and a DL382 TCU tune. The EA288evo block handles this effortlessly.", zeroToHundred: "6.1s", hundredToTwoHundred: "14.5s" } ],
