            tuningPotential: [ { stage: "Stage 1", power: "320 - 330 hp", notes: "An ECU remap safely brings this engine past 320hp and 700 Nm of torque, offering phenomenal value. Also significantly improves factory throttle response.", zeroToHundred: "5.5s", hundredToTwoHundred: "14.0s" }, { stage: "Stage 2", power: "340 - 350 hp", notes: "Requires DPF removal, SCR delete (where legal), and an upgraded intercooler. The factory turbocharger approaches its limit here.", zeroToHundred: "5.1s", hundredToTwoHundred: "12.5s" }, { stage: "Stage 3", power: "400 - 430+ hp", notes: "Requires GTB2260VK hybrid turbo, CP3 fuel pump conversion, and an aggressive ZF8 TCU tune.", zeroToHundred: "4.5s", hundredToTwoHundred: "10.8s" } ],
