            tuningPotential: [ { stage: "Stage 1", power: "340 - 350 hp", notes: "An ECU remap transforms this engine, safely bringing it to 750 Nm of torque. Most importantly, tuning completely eliminates the dangerous factory throttle lag, making the car much safer to drive in traffic.", zeroToHundred: "4.9s", hundredToTwoHundred: "12.5s" }, { stage: "Stage 2", power: "360 - 370 hp", notes: "Requires DPF removal, SCR delete (where legal), and an upgraded intercooler. The factory turbocharger approaches its limit here.", zeroToHundred: "4.5s", hundredToTwoHundred: "11.0s" }, { stage: "Stage 3", power: "410 - 430+ hp", notes: "Requires GTB2260VK hybrid turbo, CP3 fuel pump conversion, and an aggressive ZF8 TCU tune.", zeroToHundred: "4.0s", hundredToTwoHundred: "9.5s" } ],
