            torqueSpecs: [ { part: "Oil Drain Plug", value: "30 Nm", note: "Replace copper crush washer." }, { part: "Spark Plugs", value: "30 Nm", note: "Torque carefully into the aluminum head. Gap strictly if tuned." }, { part: "Wheel Bolts", value: "120 Nm", note: "Tighten strictly in a star pattern." }, { part: "Turbo V-Band Clamps", value: "12 Nm", note: "Ensure perfect seating to prevent exhaust leaks in the valley." }, { part: "PCV Bolts", value: "9 Nm", note: "Tighten evenly in a crisscross pattern." }, { part: "Engine Mount Bolts", value: "90 Nm + 90 degrees", note: "Use new stretch bolts." } ],
