            tuningPotential: [ { stage: "Stage 1", power: "235 - 245 hp", notes: "An ECU software flash yields excellent gains, significantly improving mid-range torque.", zeroToHundred: "7.1s", hundredToTwoHundred: "19.5s" }, { stage: "Stage 2", power: "260 - 275 hp", notes: "Requires a high-flow downpipe and upgraded intercooler. TCU tune recommended.", zeroToHundred: "6.7s", hundredToTwoHundred: "17.8s" }, { stage: "Stage 3 (IS38 Swap)", power: "330 - 360+ hp", notes: "Swapping to the larger IS38 turbo transforms the car. DL382 TCU tune is mandatory.", zeroToHundred: "5.8s", hundredToTwoHundred: "14.2s" } ],
