        engineMechanical: [ { interval: "150,000 km", timeLimit: "N/A", task: "Timing Chain Tensioner Inspection", details: "Listen carefully for a metallic cold-start rattle. Replace upper tensioners immediately if noise persists over 3 seconds to prevent catastrophic chain jump.", parts: ["Upper Tensioners", "Sealant"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "800 - 1200 EUR" }, { interval: "150,000 km", timeLimit: "N/A", task: "Intake Manifold Swirl Flap Check", details: "Inspect the plastic linkages connecting the electronic actuators to the swirl flaps for excessive wear, jamming, or carbon blockage.", parts: ["Linkage Repair Kit"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "50 - 100 EUR" } ],
