        engineMechanical: [ { interval: "150,000 km", timeLimit: "N/A", task: "Timing Chain Tensioner Inspection", details: "Listen carefully for a metallic cold-start rattle. Replace upper tensioners immediately if noise persists over 3 seconds to prevent catastrophic chain jump.", parts: ["Upper Tensioners", "Sealant"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "800 - 1200 EUR" }, { interval: "150,000 km", timeLimit: "N/A", task: "Intake Manifold Swirl Flap Check", details: "Inspect the plastic linkages connecting the electronic actuators to the swirl flaps for excessive wear, jamming, or carbon blockage.", parts: ["Linkage Repair Kit"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "50 - 100 EUR" } ],
        fluidsAndDrivetrain: [ { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Completely flush the DOT 4 fluid to prevent ABS module corrosion.", parts: ["1.0L DOT 4 Fluid"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 - 100 EUR" }, { interval: "60,000 km", timeLimit: "4 years", task: "S-tronic DSG Fluid & Filter Change", details: "Critical maintenance for the DL501 to remove clutch dust.", parts: ["7.0L DSG Fluid", "Filters"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "300 - 450 EUR" }, { interval: "120,000 km", timeLimit: "N/A", task: "DSG MTF Gear Oil Change", details: "Drain and fill the mechanical gear section of the transmission.", parts: ["4.5L 75W-90 MTF Fluid"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "120 - 180 EUR" }, { interval: "80,000 km", timeLimit: "N/A", task: "Front Differential Fluid Change", details: "Drain and fill gear oil to prevent bearing wear.", parts: ["75W-90 GL-4"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "60 - 90 EUR" }, { interval: "80,000 km", timeLimit: "N/A", task: "Rear Differential Fluid Change", details: "Change hypoid gear oil for Quattro models.", parts: ["75W-90 GL-5"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "60 - 90 EUR" } ], 
