            { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter Replacement", details: "Crucial for diesel turbo efficiency and preventing overly rich mixtures that clog the DPF.", parts: ["Air Filter Element"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 - 45 EUR" }, 
            { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Air Filter Replacement", details: "Replace with a high-quality activated carbon filter to eliminate outside odors and filter PM2.5.", parts: ["Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "20 - 35 EUR" }, 
            { interval: "30,000 km", timeLimit: "2 years", task: "Fuel Filter Replacement", details: "Absolutely critical to protect the fragile Bosch CP4.2 fuel pump from particulate contamination.", parts: ["Fuel Filter Unit"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "50 - 80 EUR" } 
