            { interval: "80,000 km", timeLimit: "6 years", task: "ZF 8HP Auto Trans Service", details: "Absolutely critical maintenance for the ZF 8-speed gearbox. Ignore Audi's lifetime fill claim to prevent catastrophic clutch wear.", parts: ["8.5L Lifeguard 8 Fluid", "Pan/Filter"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "350 - 500 EUR" }, 
            { interval: "80,000 km", timeLimit: "N/A", task: "Transfer Case Fluid Change", details: "Drain and fill the specialized fluid in the center differential.", parts: ["1.0L Transfer Case Fluid"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "80 - 120 EUR" }, 
            { interval: "80,000 km", timeLimit: "N/A", task: "Front Differential Fluid Change", details: "Crucial to prevent front differential bearing whine.", parts: ["75W-90 GL-4"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "60 - 90 EUR" }, 
            { interval: "80,000 km", timeLimit: "N/A", task: "Rear Differential Fluid Change", details: "Crucial for Quattro models to prevent shuddering during tight turns.", parts: ["75W-90 GL-5"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "60 - 90 EUR" } 
