            { interval: "100,000 km", timeLimit: "6 years", task: "Glow Plug Replacement", details: "Replace all 4 glow plugs. Euro 6 engines rely heavily on glow plugs for smooth DPF regeneration cycles.", parts: ["4x Glow Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 - 160 EUR" }, 
            { interval: "30,000 km", timeLimit: "N/A", task: "CP4 Metering Valve Inspection", details: "Remove the valve on top of the fuel pump to check for shiny metal flakes indicating imminent pump failure.", parts: ["Diagnostic"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "30 - 50 EUR" }, 
            { interval: "150,000 km", timeLimit: "N/A", task: "Injector Copper Seals Replacement", details: "Replace copper crush washers to prevent blow-by and the notorious 'black death' injector seizing.", parts: ["4x Copper Seals"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "150 - 250 EUR" }, 
            { interval: "100,000 km", timeLimit: "6 years", task: "Serpentine Belt & Tensioner", details: "Inspect and replace the main drive belt and tensioner pulley to prevent belt snapping.", parts: ["Belt Kit", "Tensioner"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 - 160 EUR" } 
