            { interval: "100,000 km", timeLimit: "N/A", task: "Four-Wheel Laser Alignment", details: "Perform a full alignment after any suspension work to prevent rapid inner tire wear.", parts: ["None"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 - 150 EUR" }, 
            { interval: "40,000 km", timeLimit: "N/A", task: "Brake Pad & Rotor Inspection", details: "Heavy braking required for the A7 wears front pads quickly.", parts: ["None"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "30 - 50 EUR" } 
