        { partName: "Fuel Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "8T0127401A", approxPrice: "55 EUR" }, crossRef: { brand: "Mann-Filter", code: "PU8008/1", approxPrice: "25 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/8t0127401a", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=8t0127401a" }, note: "Replace every 30k km to save the CP4 pump." },
        { partName: "DSG Transmission Filter", category: "Drivetrain", oem: { brand: "Audi Genuine", code: "0CK325421A", approxPrice: "45 EUR" }, crossRef: { brand: "Vaico", code: "V103223", approxPrice: "25 EUR", source: "Aftermarket", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/0ck325421a", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=0ck325421a" }, note: "Internal filter for the DL382 7-speed S-tronic." }
